import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\((.+?)\)|.') -> dict:
    """
    Extract matches from every regular text file in a directory.

    For each file, matches are collected with the provided regular expression.
    The default pattern treats text inside parentheses as one match and every
    character outside parentheses as individual matches.

    Args:
        directory_path: Directory containing text files.
        regex_pattern: Regular expression used to extract matches.

    Returns:
        A dictionary mapping file names (without path) to lists of matches.
    """
    results = {}

    base_dir = Path(directory_path)
    if not base_dir.exists() or not base_dir.is_dir():
        return results

    for file_name in sorted(glob.glob(os.path.join(directory_path, "*"))):
        file_path = Path(file_name)
        if not file_path.is_file():
            continue

        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        try:
            matches = re.findall(regex_pattern, content, flags=re.DOTALL)
        except re.error:
            raise

        normalized_matches = []
        for match in matches:
            if isinstance(match, tuple):
                parts = [part for part in match if part]
                if len(parts) == 1:
                    normalized_matches.append(parts[0])
                elif len(parts) > 1:
                    normalized_matches.append("".join(parts))
                else:
                    normalized_matches.append("")
            else:
                normalized_matches.append(match)

        results[file_path.name] = normalized_matches

    return results

