import os
import shutil

def task_func(path):
    os.makedirs(path, exist_ok=True)
    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    frames = []

    for filename in sorted(os.listdir(path)):
        file_path = os.path.join(path, filename)

        if not os.path.isfile(file_path):
            continue
        if not filename.lower().endswith(".json"):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue

        if isinstance(data, list):
            if len(data) == 0:
                current_df = pd.DataFrame()
            elif all(isinstance(item, dict) for item in data):
                current_df = pd.DataFrame(data)
            else:
                current_df = pd.DataFrame({"value": data})
        elif isinstance(data, dict):
            current_df = pd.DataFrame([data])
        else:
            current_df = pd.DataFrame({"value": [data]})

        if current_df.empty:
            current_df = pd.DataFrame(columns=["Source"])
        else:
            if "Source" in current_df.columns:
                current_df = current_df.drop(columns=["Source"])
            current_df.insert(0, "Source", filename)

        frames.append(current_df)

        destination = os.path.join(processed_dir, filename)
        if os.path.exists(destination):
            os.remove(destination)
        shutil.move(file_path, destination)

    if frames:
        df = pd.concat(frames, ignore_index=True, sort=False)
    else:
        df = pd.DataFrame()

    return df

