from openpyxl import load_workbook

def task_func(directory_path='./xlsx_files/'):
    processed_files = 0

    if not os.path.isdir(directory_path):
        return processed_files

    file_paths = sorted(
        path for path in glob.glob(os.path.join(directory_path, '*'))
        if os.path.isfile(path) and path.lower().endswith('.xlsx')
    )

    for file_path in file_paths:
        workbook = None
        try:
            workbook = load_workbook(file_path)
            modified = False

            for worksheet in workbook.worksheets:
                for row in worksheet.iter_rows():
                    for cell in row:
                        value = cell.value
                        if isinstance(value, str) and cell.data_type != 'f' and '"' in value:
                            escaped_value = value.replace('"', '\\\\\"')
                            if escaped_value != value:
                                cell.data_type = 's'
                                cell._value = escaped_value
                                modified = True

            if modified:
                workbook.save(file_path)

            processed_files += 1
        except Exception:
            continue
        finally:
            if workbook is not None:
                try:
                    workbook.close()
                except Exception:
                    pass

    return processed_files

