import docx

def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(source_directory)
    if not source_path.is_dir():
        raise FileNotFoundError(f"Source directory does not exist: {source_directory}")

    target_path = Path(target_directory)
    target_path.mkdir(parents=True, exist_ok=True)

    allowed_extensions = {".txt", ".docx", ".xlsx", ".csv"}

    def extract_text(file_path: Path) -> str:
        suffix = file_path.suffix.lower()

        if suffix in {".txt", ".csv"}:
            return file_path.read_text(encoding="utf-8", errors="replace")

        if suffix == ".docx":
            document = docx.Document(str(file_path))
            parts = []

            for element in document.element.body:
                tag = element.tag
                if tag.endswith("}p"):
                    paragraph = docx.text.paragraph.Paragraph(element, document)
                    parts.append(paragraph.text)
                elif tag.endswith("}tbl"):
                    table = docx.table.Table(element, document)
                    for row in table.rows:
                        parts.append("\t".join(cell.text for cell in row.cells))

            return "\n".join(parts)

        if suffix == ".xlsx":
            sheets = pd.read_excel(str(file_path), sheet_name=None, dtype=object)
            sheet_texts = []

            for frame in sheets.values():
                if frame is None or frame.empty:
                    sheet_texts.append("")
                    continue

                rows = []
                for _, row in frame.iterrows():
                    values = ["" if pd.isna(value) else str(value) for value in row.tolist()]
                    rows.append("\t".join(values))
                sheet_texts.append("\n".join(rows))

            return "\n\n".join(sheet_texts)

        return ""

    converted_count = 0
    input_files = [
        path for path in sorted(source_path.iterdir())
        if path.is_file() and path.suffix.lower() in allowed_extensions
    ]

    for file_path in input_files:
        try:
            text = extract_text(file_path)
            output_file = target_path / f"{file_path.stem}.csv"
            pd.DataFrame({"Text": [text]}).to_csv(output_file, index=False)
            converted_count += 1
        except Exception:
            continue

    return converted_count

import pytz
import numpy as np
from dateutil.parser import parse
import math
import calendar
from datetime import datetime, timedelta

MOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])

_SYNODIC_MONTH = 29.53058867
_MOON_EPOCH_UTC = pytz.UTC.localize(datetime(2000, 1, 6, 18, 14, 0))


def _safe_localize(tz, naive_dt):
    try:
        return tz.localize(naive_dt, is_dst=None)
    except pytz.AmbiguousTimeError:
        return tz.localize(naive_dt, is_dst=True)
    except pytz.NonExistentTimeError:
        shifted = naive_dt + timedelta(hours=1)
        try:
            return tz.localize(shifted, is_dst=True)
        except Exception:
            return tz.localize(shifted, is_dst=False)


def _coerce_datetime(date_str, from_tz, to_tz):
    dt = parse(date_str)

    try:
        from_zone = pytz.timezone(from_tz)
        to_zone = pytz.timezone(to_tz)
    except Exception as exc:
        raise ValueError("Invalid timezone name") from exc

    if dt.tzinfo is None:
        dt = _safe_localize(from_zone, dt)
    else:
        dt = dt.astimezone(from_zone)

    return dt.astimezone(to_zone)


def _reference_year_for(year):
    years = MOON_PHASES_YEARS.astype(int)
    idx = int(np.argmin(np.abs(years - year)))
    return int(years[idx])


def _reference_datetime(local_dt, reference_year):
    last_day = calendar.monthrange(reference_year, local_dt.month)[1]
    day = min(local_dt.day, last_day)
    naive_ref = datetime(
        reference_year,
        local_dt.month,
        day,
        local_dt.hour,
        local_dt.minute,
        local_dt.second,
        local_dt.microsecond,
    )
    return _safe_localize(local_dt.tzinfo, naive_ref)


def _moon_phase_fraction(dt_utc):
    elapsed_days = (dt_utc - _MOON_EPOCH_UTC).total_seconds() / 86400.0
    age_days = elapsed_days % _SYNODIC_MONTH
    return age_days / _SYNODIC_MONTH


def task_func(date_str, from_tz, to_tz):
    local_dt = _coerce_datetime(date_str, from_tz, to_tz)

    reference_year = _reference_year_for(local_dt.year)
    reference_dt = _reference_datetime(local_dt, reference_year)

    reference_phase = _moon_phase_fraction(reference_dt.astimezone(pytz.UTC))
    delta_days = (local_dt.astimezone(pytz.UTC) - reference_dt.astimezone(pytz.UTC)).total_seconds() / 86400.0

    phase = (reference_phase + delta_days / _SYNODIC_MONTH) % 1.0

    # Map lunar age to illumination-like scale:
    # 0.0 = new moon, 1.0 = full moon
    illumination = 0.5 * (1.0 - math.cos(2.0 * math.pi * phase))

    return float(min(1.0, max(0.0, illumination)))

from collections import Counter
from operator import itemgetter
import itertools


def task_func(word_dict):
    """
    Count the frequency of each letter appearing in the dictionary keys.

    Parameters
    ----------
    word_dict : dict
        A dictionary whose keys are words.

    Returns
    -------
    dict
        A dictionary mapping each letter to its frequency across all words.
    """
    if not word_dict:
        return {}

    counter = Counter()

    for word in word_dict.keys():
        if word is None:
            continue

        for ch in str(word):
            if ch.isalpha():
                counter[ch] += 1

    return dict(counter)

