def task_func(goals, penalties, rng_seed=None):
    """
    Create a DataFrame with columns ['Team', 'Match Result'].

    The function supports either:
    - integers: treated as upper bounds for random goals/penalties and as a
      basis for the number of teams, or
    - iterables: treated as per-team upper bounds for random goals/penalties.

    Penalties are converted into fines using a predefined cost.
    """
    if rng_seed is not None:
        seed(rng_seed)

    FINE_PER_PENALTY = 100

    def _is_non_string_iterable(obj):
        return hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes, bytearray))

    def _normalize(value):
        if _is_non_string_iterable(value):
            return [max(0, int(v)) for v in value], None
        return None, max(0, int(value))

    goal_limits, goal_limit = _normalize(goals)
    penalty_limits, penalty_limit = _normalize(penalties)

    if goal_limits is not None and penalty_limits is not None:
        n_teams = min(len(goal_limits), len(penalty_limits))
    elif goal_limits is not None:
        n_teams = len(goal_limits)
    elif penalty_limits is not None:
        n_teams = len(penalty_limits)
    else:
        n_teams = max(goal_limit, penalty_limit, 1)

    records = []
    for idx in range(n_teams):
        max_goals = goal_limits[idx] if goal_limits is not None else goal_limit
        max_penalties = penalty_limits[idx] if penalty_limits is not None else penalty_limit

        scored_goals = randint(0, max_goals)
        committed_penalties = randint(0, max_penalties)
        fines = committed_penalties * FINE_PER_PENALTY

        records.append(
            {
                "Team": f"Team {idx + 1}",
                "Match Result": (
                    f"Goals: {scored_goals}, "
                    f"Penalties: {committed_penalties}, "
                    f"Fines: {fines}"
                ),
            }
        )

    return pd.DataFrame(records, columns=["Team", "Match Result"])

import re
import os
import shutil

def task_func(source_dir, target_dir, file_pattern=r'\b[A-Za-z0-9]+\.(txt|doc|docx)\b'):
    """
    Search source_dir recursively for files whose full path matches file_pattern,
    write all matching paths to a configuration file inside target_dir, and
    return the path to that configuration file.
    """
    os.makedirs(target_dir, exist_ok=True)

    config_path = os.path.join(target_dir, "found_files.conf")

    try:
        pattern = re.compile(file_pattern)
    except re.error:
        # Fall back to a literal search if the supplied regex is invalid.
        pattern = re.compile(re.escape(file_pattern))

    matches = []

    if os.path.isdir(source_dir):
        for root, _, files in os.walk(source_dir):
            for name in files:
                full_path = os.path.normpath(os.path.join(root, name))
                if pattern.search(full_path) or pattern.search(name):
                    matches.append(full_path)

    matches = sorted(set(matches))

    with open(config_path, "w", encoding="utf-8") as config_file:
        for path in matches:
            config_file.write(path + "\n")

    return os.path.abspath(config_path)

