from collections import Counter

def task_func(strings: list) -> dict:
    """
    Count occurrences of each distinct string in the input list.

    Args:
        strings: A list of strings to analyze.

    Returns:
        A dictionary mapping each unique string to its occurrence count.
    """
    if strings is None:
        return {}

    counts = Counter()
    for item in strings:
        counts[str(item)] += 1

    return dict(counts)

import pandas as pd
import numpy as np

def task_func(file_path="data.csv", columns=["A", "B", "C"]):
    if isinstance(columns, str):
        columns = [columns]
    else:
        columns = list(columns)

    df = pd.read_csv(file_path)

    def _convert_numeric(series):
        if pd.api.types.is_numeric_dtype(series):
            return series.astype(float)
        converted = pd.to_numeric(series, errors="coerce")
        if converted.notna().sum() == series.notna().sum():
            return converted.astype(float)
        return series

    df = df.apply(_convert_numeric)

    missing_columns = [col for col in columns if col not in df.columns]
    if missing_columns:
        raise KeyError(f"Missing columns in CSV: {missing_columns}")

    plot_data = df.loc[:, columns].apply(pd.to_numeric, errors="coerce").astype(float)

    ax = plot_data.plot()

    cube_root_series = pd.Series(
        np.cbrt(plot_data.to_numpy().ravel()),
        name="cube_root",
    )

    return df, ax, cube_root_series
